mapper.select:
SELECT af.after_id AS afterId, af.commodity_id AS commodityId, af.commodity_name AS skuName, af.thumbnail_url AS imageUrl, af.after_price AS afterPrice, ssku.sku_id AS originalSkuId, ssku.commodity_store_sku_id AS skuId, ssku.commodity_store_sku_price AS skuPrice, ssku.commodity_store_sku_strike_price AS strikePrice, sspu.many_copy AS manyCopy, sspu.package_fee AS packageFee, sspu.commodity_store_spu_id AS spuId FROM commodity_after_order af LEFT JOIN commodity_spus spu ON spu.commodity_id = af.commodity_id AND spu.deleted = 0 LEFT JOIN commodity_store_spu sspu ON sspu.commodity_id = spu.commodity_id AND sspu.deleted = 0 AND sspu.store_id = #{storeId} LEFT JOIN commodity_store_sku ssku ON ssku.commodity_id = af.commodity_id AND ssku.store_id = #{storeId} AND ssku.deleted = 0 WHERE af.deleted = 0 AND af.after_id IN
#{afterId}
GROUP BY af.commodity_id
